<?php $pageTitle='Shop';require 'includes/header.php';$categories=db()->query('SELECT * FROM categories')->fetchAll();$items=products();$q=trim($_GET['q']??'');$cat=(int)($_GET['category']??0);$sort=$_GET['sort']??'new';$max=(float)($_GET['max']??0);$items=array_values(array_filter($items,fn($i)=>(!$q||stripos($i['name'].' '.$i['category'],$q)!==false)&&(!$cat||$i['category_id']==$cat)&&(!$max||$i['price']<=$max)));if($sort==='price')usort($items,fn($a,$b)=>$a['price']<=>$b['price']);if($sort==='price_desc')usort($items,fn($a,$b)=>$b['price']<=>$a['price']);?><section class="container section-space"><div class="eyebrow">DISCOVER SAHORA</div><h1 class="page-title">Shop <em>Collection</em></h1><p class="muted">Everyday essentials, elevated.</p><div class="row g-4 mt-3"><aside class="col-lg-3"><form class="filter-panel" method="get"><h5>Filter products</h5><label class="form-label mt-3">Search</label><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Product name"><label class="form-label mt-3">Category</label><select name="category" class="form-select"><option value="0">All categories</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=$cat==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><label class="form-label mt-3">Maximum price (Rs.)</label><input class="form-control" name="max" type="number" min="0" value="<?=$max?:''?>"><label class="form-label mt-3">Sort by</label><select name="sort" class="form-select"><option value="new">Newest</option><option value="price" <?=$sort==='price'?'selected':''?>>Price: low to high</option><option value="price_desc" <?=$sort==='price_desc'?'selected':''?>>Price: high to low</option></select><button class="btn btn-gold w-100 mt-4">Apply Filters</button></form></aside><div class="col-lg-9"><div class="d-flex justify-content-between mb-3"><span class="muted"><?=count($items)?> products</span><span class="eyebrow">RETAIL + WHOLESALE</span></div><div class="row g-3"><?php foreach($items as $item)require 'includes/product_card.php';if(!$items)echo '<p>No matching products found.</p>';?></div></div></div></section><?php require 'includes/footer.php';?>